// Database identity. A database is a `*.db` file inside the user's Nextcloud
// files, identified by its Nextcloud file id (stable across rename/move).

/** One selectable UPM database. */
export interface DatabaseDescriptor {
  /** Nextcloud file id as a string; '' while the database has not been saved. */
  id: string;
  /** User-facing label. */
  label: string;
  /** Path relative to the user's files, e.g. "upm/upm.db". */
  path: string;
  /** False when the file cannot be overwritten (e.g. a read-only share). */
  canWrite?: boolean;
}

/** A database as reported by the server, before a label is applied. */
export interface RemoteDatabase {
  id: string;
  path: string;
  name: string;
  size: number;
  mtime: number;
  canWrite: boolean;
}

/** Derive a display label from a path ("upm/work.db" -> "work"). */
export function labelFromPath(path: string): string {
  const name = path.split('/').pop() ?? path;
  return name.replace(/\.db$/i, '') || name;
}

/** True when both descriptors point at the same file. */
export function sameDatabase(a: DatabaseDescriptor, b: DatabaseDescriptor): boolean {
  return a.id !== '' && a.id === b.id;
}
